"""Randomized layout/recovery roundtrip over random type graphs."""
import random, sys
sys.path.insert(0, '/workspace/project/src')
sys.path.insert(0, '/workspace/tmp/tests')
from kbuild import ktest, b64, le
from eywa.ast import TypeDef, TypeTable
from eywa import oracles, wire

random.seed(7)

def rand_types():
    defs = [
        {"name": "B", "kind": "bool"},
        {"name": "C", "kind": "char"},
        {"name": "I1", "kind": "int", "bits": 1},
        {"name": "I8", "kind": "int", "bits": 8},
        {"name": "I20", "kind": "int", "bits": 20},
        {"name": "I64", "kind": "int", "bits": 64},
        {"name": "E", "kind": "enum", "values": ["ea", "eb", "ec"]},
        {"name": "S0", "kind": "string", "maxsize": 0},
        {"name": "S3", "kind": "string", "maxsize": 3},
    ]
    # random aggregates over existing names
    for i in range(14):
        existing = [d["name"] for d in defs]
        r = random.random()
        n = "T%d" % i
        if r < 0.35:
            defs.append({"name": n, "kind": "struct",
                         "fields": [["f%d" % j, random.choice(existing)] for j in range(random.randint(1, 4))]})
        elif r < 0.65:
            defs.append({"name": n, "kind": "array", "element": random.choice(existing),
                         "size": random.randint(0, 3)})
        elif r < 0.85:
            defs.append({"name": n, "kind": "alias", "target": random.choice(existing)})
        else:
            defs.append({"name": n, "kind": "enum", "values": ["v%d" % j for j in range(random.randint(1, 5))]})
    return defs

def rand_value(d, defs):
    k = d["kind"]
    if k == 'bool':
        return random.random() < 0.5
    if k == 'char':
        return chr(random.randint(0, 255))
    if k == 'int':
        return random.randint(0, (1 << d["bits"]) - 1)
    if k == 'enum':
        return random.choice(d["values"])
    if k == 'string':
        n = random.randint(0, d["maxsize"])
        return "".join(chr(random.choice([0, 65, 66, 255, 9])) for _ in range(n)) if n else ""
    if k == 'array':
        return [rand_value(by_name[d["element"]], defs) for _ in range(d["size"])]
    if k == 'struct':
        return {f: rand_value(by_name[t], defs) for (f, t) in d["fields"]}
    raise AssertionError

def truncate(s):
    return s.split("\x00")[0]

by_kind = {}

for trial in range(300):
    defs = rand_types()
    by_name = {d["name"]: d for d in defs}
    types = TypeTable(TypeDef.from_json(d) for d in defs)
    # params: 1..4 random types; result random or void
    params = [("p%d" % i, random.choice(list(by_name))) for i in range(random.randint(1, 4))]
    if random.random() < 0.2:
        result = None
    else:
        result = ("res", random.choice(list(by_name)))
    slots, base = oracles.layout(types, params, result)
    # build KTEST objects from random values
    objs = []
    counter = [0]
    def emit(tname, v):
        d = by_name[tname]
        k = d["kind"]
        if k == 'alias':
            emit(d["target"], v)
        elif k == 'bool':
            objs.append(("x%d" % counter[0], le(1 if v else 0, 1))); counter[0] += 1
        elif k == 'char':
            objs.append(("x%d" % counter[0], le(ord(v), 1))); counter[0] += 1
        elif k == 'int':
            w = oracles.int_width(d["bits"])
            objs.append(("x%d" % counter[0], le(v, w))); counter[0] += 1
        elif k == 'enum':
            objs.append(("x%d" % counter[0], le(d["values"].index(v), 4))); counter[0] += 1
        elif k == 'string':
            counter[0] += 1
            for i in range(d["maxsize"]):
                cp = ord(v[i]) if i < len(v) else 0
                objs.append(("x%d" % counter[0], le(cp, 1))); counter[0] += 1
        elif k == 'array':
            counter[0] += 1
            for i in range(d["size"]):
                emit(d["element"], v[i])
        elif k == 'struct':
            counter[0] += 1
            for (f, t) in d["fields"]:
                emit(t, v[f])
        elif k == 'void':
            pass
    exp_inputs = {}
    for (n, t) in params:
        v = rand_value(by_name[t], defs)
        exp_inputs[n] = v
        emit(t, v)
    exp_model = None
    if result is not None:
        v = rand_value(by_name[result[1]], defs)
        exp_model = v
        emit(result[1], v)
    assert counter[0] == base, (counter[0], base)
    # shuffle object order
    random.shuffle(objs)
    data = wire.decode_payload(b64(ktest(objs)))
    got_objs = wire.decode_objects(data)
    expected = {int(s[0][1:]): s[2] for s in slots}
    assert set(got_objs) == set(expected)
    values = {i: int.from_bytes(b, 'little') for (i, b) in got_objs.items()}
    inputs, model = oracles.recover(types, params, result, values)
    # strings recover truncated; everything else exact
    def norm(tname, v):
        d = by_name[tname]
        if d["kind"] == 'alias':
            return norm(d["target"], v)
        if d["kind"] == 'string':
            return truncate(v)
        if d["kind"] == 'array':
            return [norm(d["element"], x) for x in v]
        if d["kind"] == 'struct':
            return {f: norm(t, v[f]) for (f, t) in d["fields"]}
        return v
    for (n, t) in params:
        assert inputs[n] == norm(t, exp_inputs[n]), (trial, n, inputs[n], exp_inputs[n])
    if result is not None:
        assert model == norm(result[1], exp_model), (trial, model, exp_model)
    else:
        assert model is None
print("T12 OK")
